import React, { useState } from 'react';
import {
  FaShoppingCart,
  FaChevronLeft,
  FaChevronRight,
  FaHeart,
  FaShoppingBag,
  FaRegHeart
} from 'react-icons/fa';
import ProductCard from '../../Components/ProductCard/ProductCard';
import RatingStars from '../../Components/RatingStars/RatingStars';
import ProductTabs from '../../Components/ProductTabs/ProductTabs'; 
import Image3 from '../../Assets/Image3.png';
import Image2 from '../../Assets/Image2.png';
import Image1 from '../../Assets/Image1.png';
import R1 from '../../Assets/R1.png';
import R2 from '../../Assets/R2.png';
import R3 from '../../Assets/R3.png';
import R4 from '../../Assets/R4.png';
import styles from './ProductReturns.module.css';

const ProductReturns = () => {
  const navigate = useNavigate();
  const [selectedSize, setSelectedSize] = useState('M');
  const [selectedColor, setSelectedColor] = useState('orange');
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [quantity, setQuantity] = useState(1);
  const [isFavorite, setIsFavorite] = useState(false);
  const [activeTab, setActiveTab] = useState('returns');

  const product = {
    id: 1,
    name: 'Noah Yellow overcoat',
    price: 5000.0,
    inStock: true,
    colors: ['orange', 'red', 'black'],
    sizes: ['M', 'L', 'XL', 'XXL'],
    images: [
      I
    ],
    description: 'This is a stylish Noah Yellow Overcoat designed with bold black and gray accents, adding a modern edge to its vibrant yellow base.',
    rating: 4.5,
    reviewCount: 121
  };

  const recommendedProducts = [
    { 
      id: 2, 
      name: 'Black Pins', 
      price: 2500.0, 
      rating: 5, 
      reviewCount: 121,
      image: '/images/products/2.jpg'
    },
    { 
      id: 3, 
      name: 'Winter Jersey', 
      price: 500.0, 
      rating: 5, 
      reviewCount: 121,
      image: '/images/products/3.jpg'
    },
    { 
      id: 4, 
      name: 'Over Coat', 
      price: 10000.0, 
      rating: 5, 
      reviewCount: 121,
      image: '/images/products/4.jpg'
    },
    { 
      id: 5, 
      name: 'Summer dress', 
      price: 1500.0, 
      rating: 5, 
      reviewCount: 121,
      image: '/images/products/5.jpg'
    },
    { 
      id: 6, 
      name: 'Full kit', 
      price: 9000.0, 
      rating: 5, 
      reviewCount: 121,
      image: '/images/products/6.jpg'
    }
  ];

  const nextImage = () => {
    setCurrentImageIndex((prev) =>
      prev === product.images.length - 1 ? 0 : prev + 1
    );
  };

  const prevImage = () => {
    setCurrentImageIndex((prev) =>
      prev === 0 ? product.images.length - 1 : prev - 1
    );
  };

  const handleAddToCart = () => {
    navigate('/cart', {
      state: {
        product: {
          ...product,
          selectedSize,
          selectedColor,
          quantity
        }
      }
    });
  };

  const handleBuyNow = () => {
    navigate('/checkout', {
      state: {
        product: {
          ...product,
          selectedSize,
          selectedColor,
          quantity
        }
      }
    });
  };

  return (
    <div className={styles.returnsPage}>
      <div className={styles.returnsContainer}>
        <div className={styles.returnsMain}>
          {/* Image Gallery */}
          <div className={styles.returnsImages}>
            <div className={styles.returnsMainImage}>
              <img
                src={product.images[currentImageIndex]}
                alt={product.name}
                className={styles.returnsMainImg}
                onError={(e) => {
                  e.target.src = '/images/product/placeholder.jpg';
                }}
              />
              <button className={`${styles.returnsNavButton} ${styles.returnsPrev}`} onClick={prevImage}>
                <FaChevronLeft />
              </button>
              <button className={`${styles.returnsNavButton} ${styles.returnsNext}`} onClick={nextImage}>
                <FaChevronRight />
              </button>
            </div>
            <div className={styles.returnsImageDotsContainer}>
              {product.images.map((_, index) => (
                <span
                  key={index}
                  className={`${styles.returnsDot} ${currentImageIndex === index ? styles.returnsActive : ''}`}
                  onClick={() => setCurrentImageIndex(index)}
                />
              ))}
            </div>
          </div>

          {/* Product Details */}
          <div className={styles.returnsDetails}>
            <div className={styles.returnsRatingFavoriteContainer}>
              <RatingStars rating={product.rating} size="large" />
              <button
                className={styles.returnsFavoriteButtonTop}
                onClick={() => setIsFavorite(!isFavorite)}
              >
                {isFavorite ? <FaHeart className={styles.returnsFilled} /> : <FaRegHeart />}
              </button>
            </div>

            <h1 className={styles.returnsTitle}>{product.name}</h1>
            <p className={styles.returnsSubDescription}>New Exclusive wear</p>

            <div className={styles.returnsPriceStock}>
              <span className={styles.returnsPrice}>Rs. {product.price.toFixed(2)}</span>
              <span className={styles.returnsStock}>{product.inStock ? 'In stock' : 'Out of stock'}</span>
            </div>

            {/* Color Selector */}
            <div className={styles.returnsColorSelector}>
              <span className={styles.returnsColorLabel}>Color</span>
              <div className={styles.returnsColorOptions}>
                {product.colors.map((color) => (
                  <div
                    key={color}
                    className={`${styles.returnsColorOptionWrapper} ${
                      selectedColor === color ? styles.returnsColorSelected : ''
                    }`}
                    onClick={() => setSelectedColor(color)}
                  >
                    <div
                      className={styles.returnsColorOption}
                      style={{
                        backgroundColor: color.toLowerCase()
                      }}
                      aria-label={color}
                    />
                  </div>
                ))}
              </div>
            </div>

            {/* Size Selector */}
            <div className={styles.returnsSizeSelector}>
              <span className={styles.returnsSizeLabel}>Size</span>
              <div className={styles.returnsSizeOptions}>
                {product.sizes.map((size) => (
                  <button
                    key={size}
                    className={`${styles.returnsSizeOption} ${selectedSize === size ? styles.returnsSizeOptionSelected : ''}`}
                    onClick={() => setSelectedSize(size)}
                  >
                    {size}
                  </button>
                ))}
              </div>
            </div>

            {/* Quantity Control */}
            <div className={styles.returnsQuantityControl}>
              <div className={styles.returnsQuantitySelector}>
                <button 
                  onClick={() => setQuantity(Math.max(1, quantity - 1))}
                  aria-label="Decrease quantity"
                >
                  -
                </button>
                <span aria-live="polite">{quantity}</span>
                <button 
                  onClick={() => setQuantity(quantity + 1)}
                  aria-label="Increase quantity"
                >
                  +
                </button>
              </div>
            </div>
            
            {/* Action Buttons */}
            <div className={styles.returnsProductActions}>
              <button className={styles.returnsAddToCart} onClick={handleAddToCart}>
                Add To Cart
              </button>
              <button className={styles.returnsBuyNow} onClick={handleBuyNow}>
                Buy Now
              </button>
            </div>

            {/* Secure Checkout */}
            <div className={styles.returnsSecureCheckout}>
              <div className={styles.returnsSecureIcons}>
                <img
                  src="/images/product/trustbag.png"
                  alt="Secure Payment"
                />
                <img
                  src="/images/product/payment-methods.png"
                  alt="Payment Methods"
                />
              </div>
              <p>Guarantee safe & secure checkout</p>
            </div>
          </div>
        </div>

        {/* Tabs Section */}
        <div className={styles.returnsTabsSection}>
          <ProductTabs activeTab={activeTab} setActiveTab={setActiveTab} />
          <div className={styles.returnsTabContent}>
            {activeTab === 'description' && (
              <div>
                <h2>Product Description</h2>
                <p>{product.description}</p>
              </div>
            )}
            {activeTab === 'review' && (
              <div>
                <h2>Customer Reviews</h2>
                <p>No reviews yet.</p>
              </div>
            )}
            {activeTab === 'returns' && (
              <div className={styles.returnsContent}>
                <h2>RETURN</h2>
                <div className={styles.returnsPolicySection}>
                  <p>
                    Our dispatch head time is 7 working days for orders that include both ready-to-strip 
                    and made-on-order pieces. If you would like the ready-to-strip pieces to be dispatched 
                    early, please mention in the NOTES section of checkout.
                  </p>
                  <p>
                    Returns must be initiated within 3 days of delivery. Returns include exchange of size, 
                    style or credit note only.
                  </p>
                  <p>
                    COD, returns and exchanges are not possible on customized garments.
                  </p>
                </div>

                <h2>SHIPPING</h2>
                <div className={styles.returnsPolicySection}>
                  <p>Enjoy free shipping on all orders.</p>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Recommended Products */}
        <div className={styles.returnsRecommendedProducts}>
          <h2>Recommended</h2>
          <p className={styles.returnsSubtitle}>You might want to take a look at these.</p>
          <div className={styles.returnsProductGrid}>
            {recommendedProducts.map((p) => (
              <ProductCard key={p.id} product={p} variant="small" />
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default ProductReturns;
